/// A statically supported Slice behavior kind.
///
/// A kind may be configured directly or invoked for an instance generated by
/// another Slice. Internal calculations without Slice outputs are not included.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
pub enum SliceKind {
    /// Calculates loan activity configured for the simulation.
    Loan,

    /// Calculates recurring fixed property-related expenses.
    FixedExpense,

    /// Calculates rental income configured for the simulation.
    Rental,

    /// Determines recurring repair occurrences.
    RepairOccurrence,

    /// Calculates the cost of a repair instance, including instances
    /// generated by a repair occurrence.
    RepairCost,
}
